// Eine Zeile für das Prüfformular: welche Dateien wurden im Ordner gefunden
const namen = $input.all().map((i) => (i.binary && i.binary.data && i.binary.data.fileName) || i.json.fileName || 'unbekannt');
return [{ json: { anzahl: namen.length, dateien: namen.join('<br>') } }];

// Vergleichsbericht als Markdown-Datei, inkl. nicht gelesener Dateien und Manipulationsverdacht
const alle = $('Dateien aufteilen').all().map((i) => i.json.datei_name);
const gelesen = $('Text vereinheitlichen').all().map((i) => i.json.datei_name);
const fehlend = alle.filter((n) => !gelesen.includes(n));
const verdacht = $('Text vereinheitlichen').all().filter((i) => i.json.manipulationsverdacht).map((i) => i.json.datei_name);
const kopf = '# Angebotsvergleich vom ' + $now.toFormat('dd.MM.yyyy HH:mm') + '\n\n'
  + 'Ausgewertet: ' + gelesen.length + ' von ' + alle.length + ' Dateien.'
  + (fehlend.length ? ' Nicht gelesen (bitte manuell prüfen): ' + fehlend.join(', ') + '.' : '') + '\n\n'
  + (verdacht.length ? '> **⚠ Verdacht auf Manipulation:** ' + verdacht.join(', ') + '. Diese Angebote enthielten Anweisungen an eine KI. Die Zeilen wurden vor der Auswertung entfernt. Angebot bitte manuell prüfen und den Anbieter darauf ansprechen.\n\n' : '');
const text = kopf + String($input.first().json.output || '');
const binary = await this.helpers.prepareBinaryData(Buffer.from(text, 'utf8'), 'Angebotsvergleich.md', 'text/markdown');
return [{ json: {}, binary: { data: binary } }];

// Gemini liefert nur den Text zurück. Dateinamen aus dem Bild-Zweig des Switch wieder anhängen (gleiche Reihenfolge).
const quelle = $('Nach Dateityp verzweigen').all(2);
return $input.all().map((item, i) => ({
  json: { ...item.json, datei_name: (quelle[i] && quelle[i].json.datei_name) || 'unbekannt', datei_typ: 'bild' },
}));

// Eine Protokollzeile je Lauf (Nachvollziehbarkeit). Bewusst ohne Personendaten.
const q = (v) => '"' + String(v ?? '').replace(/"/g, '""').replace(/\r?\n/g, ' ') + '"';
const alle = $('Dateien aufteilen').all().map((i) => i.json.datei_name);
const gelesen = $('Text vereinheitlichen').all().map((i) => i.json.datei_name);
const fehlend = alle.filter((n) => !gelesen.includes(n));
const verdacht = $('Text vereinheitlichen').all().filter((i) => i.json.manipulationsverdacht).map((i) => i.json.datei_name);
let bericht = '';
try { bericht = $('Bericht in Ordner schreiben').first().json.fileName; } catch (e) {}
let bemerkung = '';
try { bemerkung = $('Auswertung starten').first().json.bemerkung || ''; } catch (e) {}
const zeile = [
  $now.toFormat('yyyy-MM-dd HH:mm:ss'),
  'ausgewertet',
  alle.length,
  gelesen.length,
  fehlend.join(', ') || 'keine',
  'Ja',
  bemerkung,
  bericht,
  'OCR: gemini-3.5-flash | Extraktion und Vergleich: groq gpt-oss-120b | RAG: ollama qwen3-embedding:0.6b',
  verdacht.join(', ') || 'keine',
].map(q).join(';') + '\n';
const binary = await this.helpers.prepareBinaryData(Buffer.from(zeile, 'utf8'), 'protokoll.csv', 'text/csv');
return [{ json: { zeile }, binary: { data: binary } }];

// Auch abgebrochene Läufe werden protokolliert. Bewusst ohne Personendaten.
